//! On Windows, embeds the application icon into `z-stackr.exe`.
//!
//! `assets/icon.ico` is generated by `scripts/make-icons.py` (the same icon as the GUI).
//! Embedding it as a resource gives the `.exe` its icon in Explorer.
//!
//! Embedding needs a resource compiler (`rc.exe` for `msvc`, `windres` for `gnu`),
//! neither guaranteed present, particularly when cross-compiling. A missing icon must
//! never fail the build, so this reports and continues.
//!
//! The gate is the TARGET OS (`CARGO_CFG_TARGET_OS`), read at run time, not a
//! `#[cfg(windows)]` on this build script: a build script is compiled for and runs on
//! the HOST, so a `cfg(windows)` here would be false whenever the Windows binary is
//! cross-compiled from Linux, and those binaries would ship without any icon.

fn main() {
    println!("cargo:rerun-if-env-changed=CARGO_CFG_TARGET_OS");
    if std::env::var("CARGO_CFG_TARGET_OS").as_deref() == Ok("windows") {
        embed_icon();
    }
}

/// Embeds `assets/icon.ico` as the executable's Windows icon resource.
///
/// A twin of `apps/stacker-gui/build.rs`'s `embed_icon`: a build script cannot share
/// code across packages without a helper crate, so an edit to one must be mirrored in
/// the other.
fn embed_icon() {
    println!("cargo:rerun-if-changed=assets/icon.ico");
    let mut res = winresource::WindowsResource::new();
    res.set_icon("assets/icon.ico");
    if let Err(e) = res.compile() {
        println!(
            "cargo:warning=could not embed the application icon ({e}); the binary will build without one"
        );
    }
}
